        .@"star_assign" => 114,
        .@"slash_assign" => 115,
        .@"percent_assign" => 116,
        .@"plus_wrap_assign" => 117,
        .@"minus_wrap_assign" => 118,
        .@"star_wrap_assign" => 119,
        .@"plus_sat_assign" => 120,
        .@"minus_sat_assign" => 121,
        .@"amp_assign" => 122,
        .@"bar_assign" => 123,
        .@"caret_assign" => 124,
        .@"lshift_assign" => 125,
        .@"lshift_wrap_assign" => 126,
        .@"rshift_assign" => 127,
        .@"arrow" => 137,
